mapper.select:
SELECT ATND_SE_CD_NM
FROM TB_ATND_SE_CD
WHERE ATND_SE_CD = #{statCd}

SELECT NVL(SUM(LEAVE_DAY), 0)
FROM TB_ATND_LEAVE_LEDGER
WHERE EMP_ID = #{empId}
  AND BASE_YEAR = #{baseYear}

SELECT NVL(SUM(-LEAVE_DAY), 0)
FROM TB_ATND_LEAVE_LEDGER
WHERE EMP_ID = #{empId}
  AND BASE_YEAR = #{baseYear}
  AND LEDGER_SE_CD = '02'

SELECT LEAVE_TYPE_CD, LEAVE_TYPE_NM, DEDUCT_DAY, PAID_YN, HALF_DAY_CD, USE_YN, SORT_ORDER
FROM TB_ATND_LEAVE_TYPE
WHERE LEAVE_TYPE_CD = #{cd}

mapper.update:
UPDATE TB_ATND_LEAVE_REQ
   SET APRVL_STTUS_CD = '02',
       RFLCT_YN       = 'Y',
       RFLCT_DT       = #{now}
 WHERE LEAVE_REQ_ID = #{leaveReqId}

mapper.select:
SELECT E.EMP_ID, E.EMP_NM, D.DEPT_NM, E.PRFL_IMG_FILE_ID, NVL(SUM(CASE WHEN L.LEDGER_SE_CD = '01' THEN L.LEAVE_DAY ELSE 0 END), 0) AS GRANTED_DAY, NVL(SUM(CASE WHEN L.LEDGER_SE_CD = '02' THEN -L.LEAVE_DAY ELSE 0 END), 0) AS USED_DAY, NVL(SUM(L.LEAVE_DAY), 0) AS REMAIN_DAY FROM TB_EMPLOYEE E LEFT JOIN TB_DEPARTMENT D ON D.DEPT_CD = E.DEPT_CD LEFT JOIN TB_ATND_LEAVE_LEDGER L ON L.EMP_ID = E.EMP_ID AND L.BASE_YEAR = #{baseYear}
E.EMP_NM LIKE '%' || #{keyword} || '%'
GROUP BY E.EMP_ID, E.EMP_NM, D.DEPT_NM, E.PRFL_IMG_FILE_ID ORDER BY D.DEPT_NM, E.EMP_NM

mapper.update:
UPDATE TB_ATND_OT_REQ
   SET APRVL_STTUS_CD = '02',
       RFLCT_YN       = 'Y',
       APPROVED_MIN   = #{approvedMin}
 WHERE OT_REQ_ID = #{otReqId}
